/* PLAYER-flag monsters carry an assigned playable race; show its tile.
 * Gender: RF_FEMALE pins female; an arbitrary RF_MALE profession
 * randomises per-monster from a stable midx hash; neuter -> base tile. */
if (mon->player_race) {
	unsigned pr = mon->player_race->ridx;
	bool female = false;
	if (rf_has(mon->race->flags, RF_FEMALE)) {
		female = true;
	} else if (rf_has(mon->race->flags, RF_MALE)) {
		female = (((unsigned)mon->midx * 2654435761u) >> 8) & 1u;
	}
	if (female && prace_female_x_attr[pr]) {
		da = prace_female_x_attr[pr];
		dc = prace_female_x_char[pr];
	} else if (prace_x_attr[pr]) {
		da = prace_x_attr[pr];
		dc = prace_x_char[pr];
	}
}
